import {palette,oklab,rgb} from './colour-model.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const [artifacts,literature]=await Promise.all(['data/artifacts.json?v=20261004','data/colour-literature.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw Error('资料读取失败');return r.json()}));
const byId=new Map(artifacts.map(a=>[a.id,a])),canvas=$('palette-canvas'),ctx=canvas.getContext('2d'),query=new URLSearchParams(location.search);let layout='bands',ground='dark',layers=[],source=query.get('object')||'drum';if(!byId.has(source))source='drum';
try{const s=JSON.parse(localStorage.getItem('jingchu-colour-composition'));if(s&&Array.isArray(s.layers)){layers=s.layers.filter(c=>byId.get(c.artifact)?.palette.some(p=>p.hex.toLowerCase()===c.hex?.toLowerCase())&&Number.isFinite(c.weight)&&c.weight>=1&&c.weight<=100).slice(0,6);layout=['bands','circles'].includes(s.layout)?s.layout:'bands';ground=s.ground==='light'?'light':'dark'}}catch{}
if(!layers.length)layers=palette(byId.get('drum')).map(c=>({hex:c.hex,weight:Math.max(1,Math.round(c.weight*100)),artifact:'drum'}));
if(query.has('hex')){const hex='#'+query.get('hex');if(/^#[0-9a-f]{6}$/i.test(hex)&&byId.get(source).palette.some(c=>c.hex.toLowerCase()===hex.toLowerCase())&&!layers.some(c=>c.hex.toLowerCase()===hex.toLowerCase()))layers=[...layers.slice(0,5),{hex,weight:25,artifact:source}]}
const images=new Map();let drawVersion=0;
function persist(){try{localStorage.setItem('jingchu-colour-composition',JSON.stringify({layers,layout,ground}))}catch{}}
function imageFor(a){if(!images.has(a.id))images.set(a.id,new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=a.displayImage||a.image}));return images.get(a.id)}
function percentages(){const total=layers.reduce((s,c)=>s+c.weight,0);return layers.map(c=>c.weight/total)}
async function draw(){const version=++drawVersion,imgs=await Promise.all(layers.map(c=>imageFor(byId.get(c.artifact))));if(version!==drawVersion)return;const dark=ground==='dark',paper=dark?'#172015':'#e7e1d4',ink=dark?'#e1d7b7':'#414233',muted=dark?'#97a183':'#8c856f';ctx.fillStyle=paper;ctx.fillRect(0,0,1200,1600);
 // A subtle paper grain generated for the composition; never modifies source photographs.
 ctx.fillStyle=dark?'#ffffff03':'#51432309';for(let y=0;y<1600;y+=8)for(let x=0;x<1200;x+=8)ctx.fillRect(x+(y%16?3:0),y,1,1);
 ctx.fillStyle=muted;ctx.font='18px sans-serif';ctx.fillText('JINGCHU / MY COLOUR STUDY',85,95);ctx.fillStyle=ink;ctx.font='54px "Songti SC",serif';ctx.fillText('我的荆楚色谱',85,180);ctx.fillStyle=muted;ctx.font='20px sans-serif';ctx.fillText('从器物出发，重新安排颜色的分量。',85,228);
 const p=percentages();
 if(layout==='bands'){let x=85;layers.forEach((c,i)=>{const width=1030*p[i];ctx.fillStyle=c.hex;ctx.fillRect(x,295,width+1,845);if(width>80&&imgs[i]){const img=imgs[i],w=Math.min(width-12,220),h=Math.min(w*img.height/img.width,250);const dw=h*img.width/img.height;ctx.drawImage(img,x+(width-dw)/2,775-h/2,dw,h)}if(width>70){ctx.save();ctx.translate(x+width/2,355);ctx.rotate(Math.PI/2);ctx.fillStyle=oklab(c.hex)[0]>.64?'#363c2e':'#eee1c6';ctx.font='20px monospace';ctx.fillText(c.hex.toUpperCase(),0,0);ctx.restore()}x+=width})}
 else{const cols=layers.length<=4?2:3,rows=Math.ceil(layers.length/cols),cellW=1030/cols,cellH=820/rows;layers.forEach((c,i)=>{const x=85+cellW*(i%cols)+cellW/2,y=325+cellH*Math.floor(i/cols)+cellH*.43,r=Math.min(cellW*.35,cellH*.32);ctx.fillStyle=c.hex;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.fillStyle=ink;ctx.font='23px monospace';ctx.textAlign='center';ctx.fillText(c.hex.toUpperCase(),x,y+r+43);ctx.fillStyle=muted;ctx.font='18px sans-serif';ctx.fillText(Math.round(p[i]*100)+'% · '+byId.get(c.artifact).title.slice(0,12),x,y+r+77);ctx.textAlign='left'})}
 ctx.strokeStyle=muted;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(85,1190);ctx.lineTo(1115,1190);ctx.stroke();ctx.font='20px "Songti SC",serif';ctx.fillStyle=ink;ctx.fillText('色彩来处',85,1240);
 layers.forEach((c,i)=>{const x=i<3?85:625,y=1285+(i%3)*54;ctx.fillStyle=c.hex;ctx.fillRect(x,y-16,25,25);ctx.fillStyle=ink;ctx.font='18px monospace';ctx.fillText(c.hex.toUpperCase()+'  '+Math.round(p[i]*100)+'%',x+40,y);ctx.fillStyle=muted;ctx.font='16px sans-serif';ctx.fillText(byId.get(c.artifact).title.slice(0,15),x+40,y+23)});
 ctx.fillStyle=muted;ctx.font='16px sans-serif';ctx.fillText('照片前景取色 · 色条占比为个人创作，不代表原器物比例',85,1510);ctx.font='14px sans-serif';ctx.fillText('荆楚 · 配色工作台 / roibai.github.io/cultureMuseum',85,1545);persist();
}
function renderLayers(){const p=percentages();$('palette-layers').innerHTML=layers.map((c,i)=>`<div class="palette-layer"><i style="--swatch:${c.hex}"></i><div><code>${c.hex.toUpperCase()}</code><output>${Math.round(p[i]*100)}%</output><input type="range" min="1" max="100" value="${c.weight}" data-weight="${i}" aria-label="${c.hex} 配色分量"><small>${esc(byId.get(c.artifact).title)}</small></div><button data-up="${i}" ${i===0?'disabled':''} aria-label="将 ${c.hex} 前移">↑</button><button data-remove="${i}" ${layers.length===1?'disabled':''} aria-label="移除 ${c.hex}">×</button></div>`).join('');document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layout===layout)));$('palette-ground').value=ground;draw()}
function renderSource(){const a=byId.get(source);$('palette-object-preview').innerHTML=`<img src="${esc(a.displayImage||a.image)}" alt="${esc(a.title)}"><p>${esc(a.material)} · ${esc(a.city)}<br>${esc(a.period)}<br><a href="object.html?id=${a.id}">器物档案 ↗</a></p>`;$('source-swatches').innerHTML=palette(a).map(c=>`<button data-add="${c.hex}" style="--swatch:${c.hex};--text:${oklab(c.hex)[0]>.64?'#363c2e':'#eee1c6'}" aria-label="加入 ${c.hex}，原照片占比 ${c.share}%">${c.hex.toUpperCase()}</button>`).join('')}
$('palette-object').innerHTML=artifacts.map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('');$('palette-object').value=source;$('palette-object').onchange=e=>{source=e.target.value;renderSource()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.add){if(layers.some(c=>c.hex.toLowerCase()===d.add.toLowerCase())){$('palette-status').textContent='这枚色卡已经在配色里，可以直接调整它的分量。';return}if(layers.length>=6){$('palette-status').textContent='已经选了六色，先移除一色，再加入新的。';return}layers.push({hex:d.add,weight:25,artifact:source});$('palette-status').textContent='已加入 '+d.add.toUpperCase();renderLayers()}if(d.remove!==undefined){layers.splice(+d.remove,1);renderLayers()}if(d.up!==undefined&&+d.up>0){const i=+d.up;[layers[i-1],layers[i]]=[layers[i],layers[i-1]];renderLayers()}if(d.layout){layout=d.layout;renderLayers()}});
$('palette-layers').oninput=e=>{if(e.target.dataset.weight===undefined)return;layers[+e.target.dataset.weight].weight=+e.target.value;percentages().forEach((p,i)=>$('palette-layers').children[i].querySelector('output').textContent=Math.round(p*100)+'%');draw()};$('palette-ground').onchange=e=>{ground=e.target.value;draw()};$('palette-reset').onclick=()=>{layers=palette(byId.get(source)).map(c=>({hex:c.hex,weight:Math.max(1,Math.round(c.weight*100)),artifact:source}));layout='bands';ground='dark';$('palette-status').textContent='已恢复当前器物的配色。';renderLayers()};
$('palette-save').onclick=async()=>{await draw();canvas.toBlob(blob=>{if(!blob){$('palette-status').textContent='图片未能导出，请重试。';return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='我的荆楚色谱.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);$('palette-status').textContent='色谱已导出，色号与器物来源一并保留。'},'image/png')};
renderSource();renderLayers();document.body.dataset.ready='true';
